  const formDrafts=new Map(),importBundles=new Map(),openGroups=new Set();
  let ruleHelp=null,helpAnchor=null,soundEnabled=localStorage.getItem('deckomantik-tournament-sound')!=='off',audioContext=null;const soundElapsed=new Map(),localCues=new Set();
