  function resultDisplay(m,round){return `<div class="t-result-readonly"><div class="t-readonly-players">${['a',...(m.b?['b']:[])].map(side=>`<div class="t-readonly-player"><strong class="t-outcome-label ${C.matchOutcome(m.result,side)}">${esc(t(C.matchOutcome(m.result,side)))}</strong><p>${esc(t('matchPoints'))} : <b>${m.result?.['points'+side.toUpperCase()]??'—'}</b></p>${round?.phase==='swiss'?`<small>${esc(t('tournamentPoints'))} : ${m.result?'+'+C.tournamentPoints(m.result,side):'—'}</small>`:''}</div>`).join('')}</div>${m.result?.turns!==null&&m.result?.turns!==undefined?`<p class="t-small">${esc(t('gameTurns'))} : ${m.result.turns}</p>`:''}${round?.bestOf>1&&m.result?`<p class="t-small muted">${esc(t('gameWins'))} : ${m.result.a} – ${m.result.b}</p>`:''}${m.result?.minutes!==null&&m.result?.minutes!==undefined?`<p class="t-match-duration">${esc(t('duration'))} : ${formatDuration(m.result.minutes)}</p>`:''}</div>`}
