  function statsMarkup(){const s=C.statistics(current);return `<div class="t-stats"><p>${esc(t('playedMatches'))}<strong>${s.matches}</strong></p><p>${esc(t('draws'))}<strong>${s.draws}</strong></p><p>${esc(t('average'))}<strong>${s.averageMinutes===null?'—':s.averageMinutes.toFixed(1)+' min'}</strong><small>${s.timed}/${s.matches}</small></p><p>${esc(t('averageTurns'))}<strong>${s.averageTurns===null?'—':s.averageTurns.toFixed(1)}</strong><small>${s.turned}/${s.matches}</small></p><p>${esc(t('averageGamePoints'))}<strong>${s.averageGamePoints===null?'—':s.averageGamePoints.toFixed(1)}</strong><small>${s.scored}/${s.matches}</small></p><p>${esc(t('deckCoverage'))}<strong>${s.decks}/${current.players.length}</strong></p></div><h3>${esc(t('cardUsage'))}</h3><div class="t-table-wrap"><table><thead><tr><th>${esc(t('card'))}</th><th>${esc(t('decks'))}</th><th>%</th></tr></thead><tbody>${s.frequency.map(row=>`<tr><td>${cardRef(row.id)}</td><td>${row.count}</td><td>${row.percent.toFixed(0)}%</td></tr>`).join('')}</tbody></table></div>`}
