    openDialog(`${p.name} · ${p.deck?.name||t('deck')}`,`${issuesMarkup(p)}${p.deck?`<details open><summary>${esc(p.deck.name)}</summary>${deckList(p.deck)}</details>`:''}${organizer?`<form id="tDeck" data-player="${esc(p.id)}"><fieldset ${canImport?'':'disabled'} style="border:0;padding:0;margin:0"><label>${esc(t('deckInput'))}<textarea name="deck" spellcheck="false" maxlength="1000000"></textarea></label><p style="margin:10px 0 16px">${esc(t('deckHelp'))}</p><label class="t-file">${esc(t('loadFile'))}<input type="file" id="tDeckFile" accept="application/pdf,.pdf,application/json,.json"><span data-import-choices></span></label>${starterPicker()}<div class="t-form-actions"><button class="t-btn t-primary" type="submit">${esc(t('importDeck'))}</button></div></fieldset></form><form id="tWaiver" data-player="${esc(p.id)}"><label>${esc(t('waiver'))}<textarea name="waiver" maxlength="1000"${canEdit()?'':' disabled'}>${esc(p.waiver||'')}</textarea></label><div class="t-form-actions"><button class="t-btn t-quiet" type="submit"${canEdit()?'':' disabled'}>${esc(t('saveWaiver'))}</button>${!canEdit()?button('unlock','unlock'):''}</div></form>`:''}`,{sticky:true,actions:p.deck?button('openDK','openDeck','t-quiet',`data-player="${esc(p.id)}"`):''});
